// Where to send a user after sign-in.
function afterLogin(target) {
  if (!target) {
    return '/';
  }
  return target;
}

module.exports = { afterLogin };

const redirects = require('../lib/redirects');

test('defaults to home', () => {
  expect(redirects.afterLogin('')).toBe('/');
});
